{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/parts/pager.json
    The list footer: a summary line and previous / next page buttons. With `numbered` it shows page numbers (1 … 4 5 6 … 21), with `moreLabel` a "Load more" button. The current page is a plain element marked aria-current="page"; the others are buttons. All text comes in through props.
    Props (p): page, pages, summary, previousLabel, nextLabel, numbered, pageLabel, moreLabel. *}
{var $v_page = ($p['page'] ?? null)}
{var $v_pages = ($p['pages'] ?? null)}
{var $v_summary = ($p['summary'] ?? null)}
{var $v_previousLabel = ($p['previousLabel'] ?? null)}
{var $v_nextLabel = ($p['nextLabel'] ?? null)}
{var $v_numbered = ($p['numbered'] ?? false)}
{var $v_pageLabel = ($p['pageLabel'] ?? null)}
{var $v_moreLabel = ($p['moreLabel'] ?? null)}
{var $v_numbers = ui_page_window($v_page, $v_pages)}
{capture $c_11}
  {capture $c_2}
    {capture $c_1}
      {=ui_text($v_summary)}
    {/capture}
    {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_1])|noescape}
  {/capture}
  {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex flex-wrap items-center gap-4'], 'children' => $c_2])|noescape}
  {capture $c_10}
    {if ui_t(ui_and([$v_moreLabel, ui_lt($v_page, $v_pages)]))}
      {capture $c_3}
        {=ui_text($v_moreLabel)}
      {/capture}
      {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Type' => 'button', 'Attrs' => ui_attrs(['data-testid', 'pager-more'])], 'children' => $c_3])|noescape}
    {/if}
    {capture $c_4}
      {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'chevron-left', 'Size' => 16]])|noescape}
    {/capture}
    {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Layout' => 'icon', 'AriaLabel' => ui_s($v_previousLabel), 'Disabled' => ui_t(ui_le($v_page, 1))], 'children' => $c_4])|noescape}
    {if ui_t($v_numbered)}
      {foreach ui_l($v_numbers) as $v_n}
        {var $v_i = $iterator->counter0}
        {if ui_t(ui_eq($v_n, null))}
          {capture $c_5}
            {=ui_text('…')}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'w-8 text-center'], 'children' => $c_5])|noescape}
        {elseif ui_t(ui_eq($v_n, $v_page))}
          {capture $c_6}
            {=ui_text($v_n)}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex h-8 min-w-8 items-center justify-center rounded bg-foreground px-2 font-bold text-background', 'Attrs' => ui_attrs(['aria-current', 'page', 'data-testid', 'pager-current'])], 'children' => $c_6])|noescape}
        {else}
          {capture $c_7}
            {=ui_text($v_n)}
          {/capture}
          {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'ghost', 'Size' => 'sm', 'Layout' => 'icon', 'Type' => 'button', 'AriaLabel' => ui_s(ui_tpl($v_pageLabel, [$v_n]))], 'children' => $c_7])|noescape}
        {/if}
      {/foreach}
    {else}
      {capture $c_8}
        {=ui_text($v_page)}
        {=ui_text(' / ')}
        {=ui_text($v_pages)}
      {/capture}
      {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'min-w-12 text-center font-bold text-foreground'], 'children' => $c_8])|noescape}
    {/if}
    {capture $c_9}
      {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'chevron-right', 'Size' => 16]])|noescape}
    {/capture}
    {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Layout' => 'icon', 'AriaLabel' => ui_s($v_nextLabel), 'Disabled' => ui_t(ui_ge($v_page, $v_pages))], 'children' => $c_9])|noescape}
  {/capture}
  {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex flex-wrap items-center gap-2'], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex flex-wrap items-center justify-between gap-4 text-xs font-semibold text-muted-foreground', 'Attrs' => ui_attrs(['data-testid', 'pager'])], 'children' => $c_11])|noescape}
